#[test]
fn models_explain_parses_an_exact_selector_and_client() {
    let cli = Cli::try_parse_from([
        "router",
        "models",
        "explain",
        "provider/model-v1",
        "--client",
        "codex",
        "--server",
        "https://router.example",
    ])
    .unwrap();
    let Some(Command::Models {
        op: ModelOp::Explain { id, client, target },
    }) = cli.command
    else {
        panic!("expected models explain");
    };
    assert_eq!(id, "provider/model-v1");
    assert_eq!(client, crate::clients::ClientKind::Codex);
    assert_eq!(target.server.as_deref(), Some("https://router.example"));
}

#[test]
fn deploy_accepts_an_ssh_server_and_public_inference_port() {
    let cli = Cli::try_parse_from([
        "router",
        "deploy",
        "--server",
        "deploy@example.test",
        "--public-port",
        "8443",
    ])
    .expect("remote deployment arguments parse");
    let Some(Command::Deploy(args)) = cli.command else {
        panic!("deploy command expected");
    };
    assert_eq!(args.server.as_deref(), Some("deploy@example.test"));
    assert_eq!(args.public_port, Some(8443));
}

#[test]
fn local_deploy_force_is_explicit_and_cannot_hide_in_status_or_remote_runs() {
    let cli = Cli::try_parse_from(["router", "deploy", "--force-update"])
        .expect("local force setting parses");
    let Some(Command::Deploy(deploy_args)) = cli.command else {
        panic!("deploy command expected");
    };
    assert!(deploy_args.force_update);

    for incompatible in ["--status", "--down", "--server"] {
        let mut argv = vec!["router", "deploy", "--force-update", incompatible];
        if incompatible == "--server" {
            argv.push("host");
        }
        assert!(
            Cli::try_parse_from(argv).is_err(),
            "accepted {incompatible}"
        );
    }
}

